                            }
                        }
                    )
                }
            }
        }
    }

    // MARK: - Project Evidence

    private var projectEvidenceSection: some View {
        HistoryProjectLinksSection(
            links: visibleRecord.projectLinks,
            projectNames: store.projectNames
        )
    }

    // MARK: - Growth Contributions

