        let trimmedInput = todayDraft.rawText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedInput.isEmpty else {
            todayLoopMessage = "请输入至少一条今天的事实、困惑或行动，再整理成卡片。"
            return
        }
        guard todayDraft.hasSelectedSessionMode else {
