            growthReportMessage = result.snapshot.canDisplayScores
                ? "周度校准报告已生成。"
                : "证据不足，已记录周度证据积累状态。"
        } catch {
            growthReportMessage = "AI 成长报告生成失败，已保留当前本地快照。"
        }
    }

