        do {
            try apiKeyStore.deleteAPIKey()
            apiKeyConfigured = false
            refreshAIServiceFromKeychainIfNeeded()
            apiKeyStatusMessage = "GLM API Key 已清除。"
            glmConnectionMessage = ""
        } catch {
            apiKeyStatusMessage = "清除 Keychain 失败。"
