                VStack(alignment: .leading, spacing: 10) {
                    Text("最近 \(summary.totalCount) 次 · 失败 \(summary.failed.count) · 成功 \(summary.successful.count)")
                        .font(.caption.monospacedDigit().weight(.semibold))
