                    .foregroundStyle(didLocateHighlightedSource ? DS.accent : DS.caution)
                Text(didLocateHighlightedSource ? "已定位到来源证据" : "已跳转到来源日期，未定位到具体证据")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(DS.mutedInk)
