import SwiftUI
import UIKit

enum HistoryFilterChipKind {
    case project
    case lens
    case cardType
    case questStatus
}

enum HistoryFilterChipMetrics {
    static func minWidth(for kind: HistoryFilterChipKind) -> CGFloat {
        switch kind {
        case .project:
            return 86
        case .lens:
            return 82
        case .cardType, .questStatus:
