        .overlay(
            RoundedRectangle(cornerRadius: DS.smallRadius, style: .continuous)
                .stroke(isFailure ? DS.caution.opacity(0.18) : Color.primary.opacity(0.05), lineWidth: 1)
        )
    }

    private var runStatusTitle: String {
        isFailure ? "失败" : "成功"
    }
